 source=Path(read(state/'registration.json')['source']);m=read(source/'manifest.json');assert m['status']=='completed' and m['metrics']['native_full_check_passed'];assert read(source/'independent_audit.json')['audit']['passed'];cmd=list(m['command']);assert '--route' in cmd and cmd[cmd.index('--router_max_convergence_count')+1]=='2';cmd[cmd.index('--router_max_convergence_count')+1]='8'
